// NexuAlpha's own coin descriptions (vi).
export const COIN_DESCRIPTIONS = Object.freeze({"a7a5":"A7A5 là stablecoin neo theo đồng rúp Nga, ra mắt năm 2025 bởi một công ty đăng ký tại Kyrgyzstan và được bảo chứng bằng tiền gửi rúp tại một ngân hàng Nga. Token chạy trên Ethereum và TRON, dùng cho thanh toán xuyên biên giới. Token và đơn vị phát hành đã bị Mỹ, Anh và EU áp lệnh trừng phạt, điều này giới hạn nơi và cách thức có thể sử dụng.","aave":"AAVE là token quản trị của Aave, giao thức cho vay phi tập trung nơi người dùng gửi tiền mã hóa để người khác vay, hoặc vay bằng tài sản thế chấp của chính mình. Người nắm giữ bỏ phiếu về nâng cấp và tham số rủi ro, và có thể staking AAVE để giúp bù đắp thâm hụt của hệ thống. Dự án khởi đầu năm 2017 với tên ETHLend, và token LEND ban đầu được chuyển đổi sang AAVE năm 2020.","aerodrome-finance":"AERO là token của Aerodrome Finance, sàn giao dịch phi tập trung và trung tâm thanh khoản trên Base, mạng layer 2 của Ethereum do Coinbase ra mắt. Aerodrome hoạt động từ năm 2023 dựa trên thiết kế của Velodrome: người nắm giữ khóa AERO thành veAERO để bỏ phiếu chọn các pool thanh khoản nhận lượng token phát hành mới. Người bỏ phiếu nhận một phần phí giao dịch và khoản khuyến khích từ các pool họ ủng hộ.","agora-dollar":"AUSD là stablecoin đô la Mỹ do Agora phát hành, ra mắt năm 2024. Mỗi token được bảo chứng bằng tiền mặt, tín phiếu Kho bạc Mỹ ngắn hạn và hợp đồng mua lại qua đêm, với dự trữ do VanEck quản lý và State Street lưu ký. AUSD được dùng cho thanh toán, giao dịch và DeFi, phát hành trên nhiều mạng như Ethereum, Sui, Mantle, Injective, Polygon và Monad.","akash-network":"AKT là token gốc của Akash Network, một thị trường phi tập trung nơi mọi người cho thuê và thuê tài nguyên điện toán đám mây, kể cả GPU dùng để huấn luyện và chạy mô hình AI. Akash được xây dựng bằng Cosmos SDK; AKT được stake để bảo vệ chuỗi, dùng trong quản trị và được chấp nhận để trả phí điện toán. Cơ chế đấu thầu mở giúp các nhà cung cấp cạnh tranh về giá cho từng lần triển khai.","akedo":"Akedo (AKE) là token trên BNB Smart Chain thuộc lĩnh vực trí tuệ nhân tạo. Dự án định hướng xoay quanh các công cụ AI, và AKE đóng vai trò token hệ sinh thái cho việc tham gia và khuyến khích.","algorand":"Algorand (ALGO) là đồng coin gốc của blockchain Algorand, do giáo sư MIT và người đoạt giải Turing Silvio Micali sáng lập, ra mắt năm 2019. Mạng dùng cơ chế bằng chứng cổ phần thuần túy (pure proof-of-stake), trong đó người tạo khối được chọn ngẫu nhiên từ những người nắm giữ. ALGO dùng để trả phí và bảo mật mạng, và chuỗi này thường được dùng cho tài sản token hóa và thanh toán.","ape-and-pepe":"Ape and Pepe (APEPE) là một meme token kết hợp hai nhân vật nổi tiếng trên mạng: chú khỉ và chú ếch Pepe. Token chạy trên mạng Polygon PoS, nơi phí chuyển khoản tương đối thấp. Giống phần lớn meme coin, nó không có chức năng giao thức riêng và sự quan tâm chủ yếu đến từ cộng đồng cùng hoạt động giao dịch.","apenft":"NFT là token của AINFT, tên cũ là APENFT, một dự án ra mắt năm 2021 trong hệ sinh thái TRON. Ban đầu dự án hướng tới việc đưa các tác phẩm nghệ thuật nổi tiếng lên blockchain dưới dạng NFT và vận hành chợ NFT; tên mới phản ánh định hướng rộng hơn, bao gồm cả dịch vụ AI. Token được dùng trên nền tảng và có mặt trên TRON, Ethereum và BNB Smart Chain.","aptos":"APT là token gốc của Aptos, blockchain layer 1 dùng bằng chứng cổ phần, mainnet ra mắt năm 2022. Dự án do các kỹ sư từng làm việc với blockchain Diem của Meta sáng lập và dùng ngôn ngữ lập trình Move cho hợp đồng thông minh. APT dùng để trả phí giao dịch, được trình xác thực và người ủy quyền staking để bảo vệ mạng, và dùng trong quản trị.","apxusd":"apxUSD là stablecoin neo theo đô la, được phát hành trên Ethereum, Base, BNB Smart Chain và Solana. Token được thiết kế để giữ giá trị khoảng một đô la Mỹ và làm đơn vị ổn định cho chuyển tiền, giao dịch và ứng dụng DeFi trên các mạng này.","arbitrum":"ARB là token quản trị của Arbitrum, nhóm mạng lớp 2 của Ethereum do Offchain Labs phát triển bằng công nghệ optimistic rollup. Người nắm giữ bỏ phiếu trong Arbitrum DAO về nâng cấp và chi tiêu ngân quỹ, còn phí giao dịch trên Arbitrum One được trả bằng ETH chứ không phải ARB. Token được phân phối qua airdrop vào tháng 3 năm 2023.","arweave":"AR là token gốc của Arweave, một blockchain chuyên lưu trữ dữ liệu vĩnh viễn, ra mắt năm 2018. Người dùng trả AR một lần để lưu tệp; một phần khoản phí được đưa vào quỹ dự phòng để chi trả lưu trữ lâu dài, còn thợ đào nhận AR khi duy trì dữ liệu. Arweave cũng vận hành AO, một lớp tính toán dành cho chương trình tự động và tác nhân AI.","aster-2":"ASTER là token của Aster, sàn giao dịch phi tập trung tập trung vào hợp đồng tương lai vĩnh cửu và giao dịch giao ngay, hoạt động chủ yếu trên BNB Chain. Token được dùng cho quản trị, khuyến khích và các quyền lợi liên quan đến phí trên nền tảng. ASTER ra mắt năm 2025 và được nắm giữ dưới dạng token trên BNB Smart Chain.","avalanche-2":"Avalanche (AVAX) là token gốc của nền tảng blockchain Avalanche, do Ava Labs ra mắt năm 2020. AVAX dùng để trả phí giao dịch (phí này bị đốt) và được các validator staking theo cơ chế bằng chứng cổ phần. Avalanche hỗ trợ hợp đồng thông minh tương thích Ethereum trên C-Chain và cho phép các dự án tạo blockchain tùy chỉnh của riêng mình; tổng cung tối đa là 720 triệu token.","axie-infinity":"AXS là token quản trị và staking của Axie Infinity, trò chơi blockchain do studio Sky Mavis của Việt Nam phát triển, trong đó người chơi sưu tầm, lai tạo và cho các sinh vật tên Axie chiến đấu. Người nắm giữ có thể stake AXS và bỏ phiếu về quỹ chung của cộng đồng, token cũng được dùng cho các hoạt động trong game như lai tạo. Trò chơi chạy chủ yếu trên Ronin, chuỗi liên kết với Ethereum do Sky Mavis xây dựng.","backpack":"BP là token gắn với Backpack, một sàn giao dịch tiền mã hóa kiêm ví tự lưu ký phát triển từ hệ sinh thái Solana, do đội ngũ đứng sau bộ sưu tập NFT Mad Lads vận hành. Token được phát hành dưới dạng SPL trên Solana, nhằm kết nối người dùng với hệ sinh thái và các chương trình cộng đồng của nền tảng. Công dụng cụ thể do đội ngũ Backpack quy định.","basic-attention-token":"BAT (Basic Attention Token) là token ERC-20 gắn với trình duyệt Brave, vốn mặc định chặn phần lớn trình theo dõi và quảng cáo. Người dùng chọn xem quảng cáo tôn trọng quyền riêng tư của Brave có thể nhận BAT và dùng nó để ủng hộ các trang web, nhà sáng tạo nội dung. Token ra mắt năm 2017 và sau đó được bắc cầu sang nhiều mạng khác như Solana và Polygon.","beldex":"BDX là coin gốc của Beldex, blockchain tập trung vào quyền riêng tư được phát triển từ mã nguồn Monero và ra mắt năm 2018. Mạng che giấu chi tiết giao dịch bằng các kỹ thuật như chữ ký vòng và địa chỉ ẩn, còn mạng masternode hỗ trợ ứng dụng nhắn tin riêng tư BChat và VPN phi tập trung BelNet. BDX dùng để trả phí và được các nhà vận hành masternode staking; trên BNB Smart Chain cũng có phiên bản BEP-20.","bfusd":"BFUSD là tài sản tính bằng đô la do Binance tạo ra để dùng bên trong nền tảng của mình, không chạy trên blockchain công khai. Tài sản này chủ yếu được dùng làm ký quỹ cho giao dịch hợp đồng tương lai, và các điều khoản do Binance quy định chứ không phải giao thức on-chain. Khác với stablecoin thông thường, BFUSD không được thiết kế để chuyển tự do giữa các ví.","bianrensheng":"币安人生 (BinanceLife) là một meme token trên BNB Smart Chain, tên tiếng Trung có nghĩa đại khái là \"cuộc đời Binance\". Token trở nên phổ biến vào năm 2025 trong cộng đồng crypto nói tiếng Trung như một cách đùa vui về hệ sinh thái Binance. Nó không có vai trò giao thức, không dùng để trả phí và không có tài sản bảo chứng; giá trị hoàn toàn phụ thuộc vào sự quan tâm của cộng đồng.","binancecoin":"BNB là đồng coin gốc của BNB Chain và gắn bó chặt chẽ với hệ sinh thái Binance. BNB ra đời năm 2017 dưới dạng token trên Ethereum, sau đó chuyển sang mạng riêng, nơi nó dùng để trả phí gas, được validator staking và tham gia quản trị. BNB có chương trình đốt định kỳ, loại bỏ vĩnh viễn một phần coin khỏi lưu thông.","bitcoin":"Bitcoin (BTC) là tiền mã hóa đầu tiên, được ra mắt năm 2009 bởi người dùng bút danh Satoshi Nakamoto. Bitcoin chạy trên blockchain bằng chứng công việc (proof-of-work) riêng, nơi thợ đào bảo vệ mạng lưới và xác nhận giao dịch; BTC được dùng để chuyển giá trị và lưu trữ giá trị dài hạn. Tổng cung tối đa là 21 triệu đồng và phần thưởng khối giảm một nửa khoảng bốn năm một lần.","bitcoin-cash":"Bitcoin Cash (BCH) là tiền mã hóa ra đời vào tháng 8 năm 2017 từ một đợt hard fork của Bitcoin. Những người ủng hộ muốn có khối lớn hơn để mạng xử lý nhiều giao dịch hơn với phí thấp và phù hợp hơn cho thanh toán hằng ngày. BCH chạy trên blockchain bằng chứng công việc riêng, dùng chung giới hạn 21 triệu đồng và lịch halving với Bitcoin, và chủ yếu được dùng cho thanh toán ngang hàng.","bitcoin-cash-sv":"Bitcoin SV (BSV) là tiền mã hóa dùng bằng chứng công việc, tách ra từ Bitcoin Cash vào tháng 11/2018. Những người ủng hộ, trong đó có nChain, muốn đi theo điều họ coi là thiết kế nguyên bản của Bitcoin, với khối rất lớn để đạt thông lượng cao trên chuỗi. BSV dùng thuật toán đào SHA-256, giới hạn 21 triệu đồng và được dùng cho thanh toán cũng như ứng dụng nhiều dữ liệu.","bitget-token":"Bitget Token (BGB) là token tiện ích của hệ sinh thái sàn Bitget. Token được dùng để giảm phí giao dịch và tham gia các sự kiện ra mắt token, đồng thời là token gas của Morph, một mạng lớp 2 của Ethereum. Cuối năm 2024, Bitget đã hợp nhất Bitget Wallet Token (BWB) vào BGB và đốt một phần lớn nguồn cung.","bittensor":"TAO là đồng coin gốc của Bittensor, một mạng phi tập trung nơi người tham gia cung cấp mô hình học máy và năng lực tính toán, rồi được thưởng dựa trên mức độ hữu ích của kết quả. Mạng được chia thành các subnet chuyên biệt, và TAO dùng để staking, đăng ký vào subnet và thanh toán dịch vụ. Giống Bitcoin, TAO có tổng cung tối đa 21 triệu và lượng phát hành mới giảm một nửa theo định kỳ.","bittorrent":"BitTorrent (BTT) là token gắn với phần mềm chia sẻ tệp BitTorrent, ra đời sau khi công ty của Justin Sun, nhà sáng lập TRON, mua lại BitTorrent Inc. năm 2018. BTT dùng để thưởng cho người chia sẻ tệp nhanh hơn, trả phí lưu trữ phi tập trung trên BTFS và làm token gas của BitTorrent Chain. Năm 2021, token được đổi mệnh giá theo tỷ lệ 1 BTT cũ lấy 1.000 BTT mới.","bitway":"Bitway (BTW) là token của một dự án tài chính phi tập trung (DeFi). Token được phát hành trên BNB Smart Chain và Ethereum nên có thể lưu trong các ví phổ biến của cả hai mạng.","blockchain-capital":"BCAP là chứng khoán số do quỹ đầu tư mạo hiểm Blockchain Capital phát hành năm 2017, đại diện cho quyền lợi kinh tế trong một quỹ của công ty này. Đây là một trong những quỹ đầu tư được token hóa sớm nhất và được tạo dưới dạng token trên Ethereum. Vì là chứng khoán chứ không phải token tiện ích, việc nắm giữ và chuyển nhượng BCAP phải tuân theo quy định chứng khoán và điều kiện về nhà đầu tư.","blockstack":"STX là token gốc của Stacks, lớp hợp đồng thông minh cho Bitcoin, trước đây có tên Blockstack. Stacks dùng cơ chế đồng thuận Proof of Transfer, trong đó thợ đào cam kết BTC để tham gia tạo khối và chuỗi được thanh toán về Bitcoin. STX dùng để trả phí giao dịch và hợp đồng thông minh viết bằng ngôn ngữ Clarity, người nắm giữ cũng có thể khóa STX qua cơ chế \"stacking\" để góp phần bảo vệ mạng.","bnb48-club-token":"KOGE là token của 48 Club, còn gọi là BNB48 Club, một cộng đồng lâu năm của những người nắm giữ BNB. Nhóm này vận hành một validator và hạ tầng liên quan trên BNB Smart Chain, còn KOGE được dùng cho tư cách thành viên và quản trị trong cộng đồng. Đây là token BEP-20 phát hành trên BNB Smart Chain.","bonk":"Bonk (BONK) là memecoin chủ đề chó trên Solana, ra mắt tháng 12 năm 2022 khi một nửa nguồn cung được airdrop cho người dùng, nhà phát triển và cộng đồng NFT của Solana. Đây không phải stablecoin hay token quản trị mà là token cộng đồng, dùng để tip và trong các ứng dụng Solana như bot giao dịch và trò chơi. Các phiên bản bắc cầu cũng tồn tại trên Ethereum, BNB Smart Chain và Arbitrum.","canton-network":"Canton Coin (CC) là token gốc của Canton Network, một blockchain dành cho các tổ chức tài chính được quản lý, với công nghệ do Digital Asset phát triển. Canton cho phép các ứng dụng riêng biệt giữ kín dữ liệu mà vẫn quyết toán giao dịch được với nhau. CC dùng để trả phí mạng và thưởng cho các validator cùng nhà cung cấp ứng dụng duy trì hoạt động của mạng.","cardano":"Cardano (ADA) là blockchain bằng chứng cổ phần ra mắt năm 2017, được phát triển theo hướng dựa trên nghiên cứu bởi đội ngũ do Charles Hoskinson – đồng sáng lập Ethereum – dẫn dắt. ADA dùng để trả phí giao dịch, ủy thác cho các stake pool bảo vệ mạng qua giao thức Ouroboros, và bỏ phiếu quản trị. Tên đồng coin lấy từ Ada Lovelace, và tổng cung tối đa là 45 tỷ.","celestia":"Celestia là blockchain dạng mô-đun chuyên về tính sẵn có của dữ liệu: lưu trữ và công bố dữ liệu giao dịch để các rollup và chuỗi khác không phải tự vận hành toàn bộ lớp đồng thuận. TIA dùng để trả phí đăng dữ liệu (\"blob\"), staking nhằm bảo mật mạng bằng bằng chứng cổ phần và tham gia quản trị. Mainnet ra mắt vào tháng 10/2023 và được xây dựng bằng Cosmos SDK.","chain-2":"Onyxcoin (XCN) là token của Onyx, dự án khởi đầu với tên Chain – đơn vị ra mắt XCN năm 2022 – trước khi đổi tên thành Onyx. XCN dùng cho quản trị giao thức Onyx và trả phí trong hệ sinh thái của dự án, bao gồm cả chuỗi Onyx riêng. Token này cũng có trên Ethereum, Base và BNB Smart Chain.","chainlink":"Chainlink (LINK) là token của một mạng oracle phi tập trung, chuyên đưa dữ liệu ngoài chuỗi như giá tài sản vào hợp đồng thông minh. LINK dùng để trả cho các nhà vận hành node và có thể staking để góp phần bảo mật dịch vụ oracle. Chainlink còn vận hành CCIP, giao thức nhắn tin xuyên chuỗi, và nguồn cấp giá của nó được nhiều dự án DeFi và tài sản token hóa sử dụng.","collector-crypt":"CARDS là token của Collector Crypt, dự án trên Solana token hóa các thẻ bài sưu tầm vật lý đã được chấm điểm, như thẻ Pokémon, và cất giữ chúng trong kho bảo quản chuyên nghiệp. Mỗi thẻ được đại diện bằng một NFT có thể giao dịch on-chain hoặc đổi lấy thẻ thật. Token CARDS gắn với hệ sinh thái nền tảng, bao gồm việc mở gói thẻ kỹ thuật số và các chương trình khuyến khích cộng đồng.","compound-governance-token":"COMP là token quản trị của Compound, một trong những giao thức cho vay sớm nhất trên Ethereum, nơi người dùng gửi tài sản mã hóa vào các pool chung hoặc vay bằng cách thế chấp. Người nắm giữ COMP đề xuất và bỏ phiếu cho các thay đổi như tài sản được hỗ trợ hay cách hoạt động của mô hình lãi suất. Tổng cung giới hạn 10 triệu, việc phân phối cho người dùng bắt đầu từ tháng 6/2020.","conflux-token":"Conflux (CFX) là đồng coin gốc của Conflux Network, một blockchain layer 1 có mainnet ra mắt năm 2020. Mạng dùng cấu trúc Tree-Graph để xử lý khối song song và kết hợp khai thác bằng chứng công việc với lớp hoàn tất bằng chứng cổ phần. CFX dùng để trả phí, làm tài sản ký quỹ cho dung lượng lưu trữ hợp đồng và để stake PoS; mạng còn có eSpace tương thích Ethereum.","convex-finance":"CVX là token của Convex Finance, giao thức trên Ethereum ra mắt năm 2021 và được xây dựng trên sàn Curve. Convex giúp nhà cung cấp thanh khoản trên Curve và người nắm giữ CRV nhận phần thưởng được tăng cường mà không cần tự khóa CRV. Người nắm giữ CVX có thể khóa token thành vlCVX để bỏ phiếu về cách Convex sử dụng lượng lớn quyền biểu quyết trên Curve, đồng thời nhận một phần phí giao thức.","cosmos":"ATOM là token gốc của Cosmos Hub, blockchain đầu tiên ra mắt trong hệ sinh thái Cosmos vào năm 2019. ATOM được staking để bảo vệ mạng bằng chứng cổ phần, dùng để trả phí giao dịch và cho phép người nắm giữ bỏ phiếu quản trị on-chain. Hub kết nối với nhiều chuỗi độc lập qua giao thức IBC (Inter-Blockchain Communication), vì vậy ATOM cũng xuất hiện trên các mạng như Osmosis và Kava.","crvusd":"crvUSD là stablecoin neo theo đô la Mỹ do Curve Finance tạo ra và ra mắt năm 2023. Người dùng đúc crvUSD bằng cách gửi tài sản mã hóa như ETH hoặc bitcoin bọc làm thế chấp, nên đây là stablecoin thế chấp vượt mức. Điểm khác biệt là cơ chế LLAMMA, giúp chuyển đổi tài sản thế chấp dần dần khi giá giảm thay vì thanh lý một lần. crvUSD được dùng trong DeFi trên Ethereum và nhiều mạng lớp 2.","crypto-com-chain":"Cronos (CRO), trước đây gọi là Crypto.com Coin, là token gốc của các blockchain Cronos do đội ngũ đứng sau Crypto.com ra mắt. CRO dùng để trả phí gas trên chuỗi Cronos EVM, staking để góp phần bảo mật mạng, và cho các phần thưởng, ưu đãi trong hệ sinh thái Crypto.com. CRO cũng tồn tại dưới dạng token ERC-20 trên Ethereum.","curve-dao-token":"CRV là token quản trị của Curve Finance, sàn giao dịch phi tập trung ra mắt năm 2020, chuyên hoán đổi các tài sản tương tự nhau như stablecoin với độ trượt giá thấp. Người dùng khóa CRV tối đa bốn năm sẽ nhận veCRV, mang lại quyền biểu quyết, một phần phí giao dịch và tiếng nói trong việc pool nào được nhận phần thưởng CRV. CRV đã được bắc cầu sang nhiều mạng như Arbitrum và Polygon.","dai":"Dai (DAI) là stablecoin phi tập trung được thiết kế để giữ giá trị gần 1 đô la Mỹ. DAI mới được tạo ra khi người dùng khóa tài sản tiền mã hóa có giá trị lớn hơn lượng DAI họ đúc vào hợp đồng thông minh; hệ thống ban đầu do MakerDAO vận hành, nay đã đổi tên thành Sky. DAI được dùng rộng rãi trong DeFi cho giao dịch, cho vay và thanh toán, và hoạt động dưới dạng token trên Ethereum.","dash":"Dash (DASH) là tiền mã hóa ra mắt năm 2014, ban đầu mang tên XCoin rồi Darkcoin, hướng tới thanh toán nhanh và chi phí thấp. Mạng kết hợp đào bằng chứng công việc với masternode, cho phép các tính năng như InstantSend để xác nhận gần như tức thì và trộn coin dựa trên CoinJoin để tăng quyền riêng tư. Một phần phần thưởng mỗi khối được đưa vào quỹ ngân khố, và chủ sở hữu masternode bỏ phiếu quyết định cách chi tiêu.","decentraland":"MANA là token của Decentraland, thế giới ảo 3D nơi người dùng sở hữu các mảnh đất dưới dạng NFT trên Ethereum; dự án mở bán token năm 2017 và mở cửa cho công chúng năm 2020. MANA được dùng để mua LAND, trang phục avatar, tên và các vật phẩm khác, còn người nắm giữ bỏ phiếu về quy tắc và tài trợ qua Decentraland DAO. Đây là token ERC-20 trên Ethereum và cũng đã được bắc cầu sang Polygon.","decred":"Decred (DCR) là tiền mã hóa ra mắt năm 2016, kết hợp khai thác bằng chứng công việc với bỏ phiếu bằng chứng cổ phần: người nắm giữ khóa DCR vào vé để phê duyệt khối và bỏ phiếu thay đổi quy tắc. Một phần phần thưởng mỗi khối đi vào ngân quỹ, và việc chi tiêu do người nắm giữ bỏ phiếu quyết định. Nguồn cung giới hạn 21 triệu coin, và mạng có tính năng trộn StakeShuffle tích hợp để bảo mật riêng tư tùy chọn.","derive":"Derive (DRV), trước đây là Lyra Finance, là sàn giao dịch phi tập trung cho quyền chọn, hợp đồng tương lai vĩnh cửu và sản phẩm cấu trúc trên chuỗi. Sàn chạy trên rollup riêng là Derive Chain, xây dựng bằng OP Stack và quyết toán trên Ethereum. DRV dùng cho quản trị và staking, người staking có thể nhận các quyền lợi gắn với hoạt động của sàn.","dogecoin":"Dogecoin (DOGE) là tiền mã hóa do Billy Markus và Jackson Palmer tạo ra năm 2013 như một trò đùa, lấy hình chú chó Shiba Inu trong meme 'doge' làm biểu tượng. Dogecoin chạy trên blockchain bằng chứng công việc riêng dùng thuật toán Scrypt và thường được đào chung (merged mining) với Litecoin. DOGE được dùng để tặng tiền boa và thanh toán nhỏ, và không có giới hạn cung cố định.","dogwifcoin":"WIF (dogwifhat) là meme coin trên Solana lấy cảm hứng từ bức ảnh một chú chó Shiba Inu đội mũ len đan màu hồng. Token ra mắt cuối năm 2023 và trở thành một trong những meme token được nhận diện rộng rãi nhất trên Solana. Ngoài việc được cộng đồng giao dịch và lan truyền, nó không có chức năng giao thức nào; WIF cũng có phiên bản trên Unichain.","doublezero":"2Z là token của DoubleZero, dự án mạng cung cấp cho các validator blockchain đường truyền cáp quang chuyên dụng, băng thông cao thay vì internet công cộng thông thường. Trọng tâm đầu tiên là Solana, nơi 2Z được phát hành dưới dạng token SPL. Token dùng để trả phí truy cập mạng và thưởng cho những người đóng góp băng thông cùng hạ tầng.","eigenlayer":"EIGEN là token của EigenCloud, tên cũ là EigenLayer, một giao thức trên Ethereum cho phép tái staking (restaking) ETH đã stake để bảo vệ các dịch vụ khác. Những dịch vụ như lớp sẵn có dữ liệu, oracle hay tác vụ AI có thể kiểm chứng tận dụng an ninh kinh tế của Ethereum thay vì tự xây dựng. Bản thân EIGEN có thể được stake để bảo chứng cho các tác vụ khó chứng minh lỗi trên chuỗi, và cũng có mặt trên Base.","ethena":"ENA là token quản trị của Ethena, giao thức phát hành USDe, một đồng đô la tổng hợp. Thay vì dựa vào tiền gửi ngân hàng, USDe được bảo chứng bằng tài sản tiền mã hóa kết hợp với vị thế bán khống hợp đồng tương lai để bù trừ, giúp giá trị luôn gần 1 đô la. Người nắm giữ ENA bỏ phiếu về rủi ro và giao thức, có thể staking token; ENA ra mắt trên Ethereum năm 2024.","ethena-usde":"Ethena USDe là đồng đô la tổng hợp do Ethena ra mắt năm 2024, hướng tới giữ giá trị gần một đô la Mỹ. Thay vì được bảo chứng bằng tiền gửi ngân hàng, USDe nắm giữ tài sản thế chấp tiền mã hóa như ETH và BTC, rồi bù trừ biến động giá bằng vị thế bán khống hợp đồng tương lai – gọi là chiến lược trung lập delta. USDe được dùng trong giao dịch và DeFi và có mặt trên nhiều mạng.","ether-fi":"ETHFI là token quản trị của ether.fi, giao thức liquid staking và restaking trên Ethereum. Người dùng gửi ETH và nhận eETH hoặc weETH, các token đại diện cho ETH đã staking, đồng thời được restaking qua EigenLayer để bảo vệ thêm các dịch vụ khác. ETHFI ra mắt năm 2024, cho phép người nắm giữ bỏ phiếu về các quyết định của giao thức; dự án cũng cung cấp thẻ thanh toán tiền mã hóa.","ethereum":"Ether (ETH) là đồng tiền gốc của Ethereum, blockchain ra mắt năm 2015 để chạy hợp đồng thông minh và ứng dụng phi tập trung. ETH dùng để trả phí giao dịch (gas) và được các validator staking để bảo vệ mạng lưới, vốn đã chuyển từ đào coin sang bằng chứng cổ phần (proof of stake) năm 2022. Rất nhiều token, stablecoin và ứng dụng DeFi hoạt động trên Ethereum, và một phần mỗi khoản phí bị đốt.","ethereum-classic":"Ethereum Classic (ETC) là blockchain Ethereum nguyên bản, tiếp tục vận hành không thay đổi sau lần chia tách năm 2016 do vụ tấn công The DAO. Mạng vẫn dùng cơ chế khai thác bằng chứng công việc (proof-of-work) và hỗ trợ hợp đồng thông minh tương thích với công cụ của Ethereum. ETC dùng để trả phí giao dịch và thưởng cho thợ đào, với nguồn cung tối đa khoảng 210,7 triệu đồng.","ethereum-name-service":"ENS là token quản trị của Ethereum Name Service, hệ thống gán các tên dễ đọc như alice.eth với địa chỉ ví và các thông tin khác. Người nắm giữ bỏ phiếu cho các đề xuất trong ENS DAO, tổ chức quản lý giao thức và ngân quỹ. Token ERC-20 này được airdrop cho chủ sở hữu tên .eth và người đóng góp vào tháng 11/2021, với tổng cung tối đa 100 triệu.","euro-coin":"EURC là stablecoin đồng euro do Circle, công ty đứng sau USDC, phát hành và được bảo chứng 1:1 bằng dự trữ tính theo euro. Token ra mắt năm 2022 (ban đầu tên Euro Coin) và được phát hành theo quy định MiCA của EU dưới dạng token tiền điện tử. EURC được dùng cho thanh toán bằng euro, trao đổi ngoại tệ và DeFi trên Ethereum, Solana, Base, Avalanche và các chuỗi khác.","falcon-finance":"Falcon USD (USDf) là đồng đô la tổng hợp do giao thức Falcon Finance tạo ra. Người dùng đúc USDf bằng cách gửi tài sản thế chấp như stablecoin, BTC hoặc ETH, và hệ thống luôn giữ giá trị thế chấp cao hơn lượng USDf đã phát hành. USDf có thể dùng như một tài sản tính bằng đô la trong DeFi hoặc stake trong giao thức để nhận sUSDf.","falcon-finance-ff":"FF là token quản trị và tiện ích của Falcon Finance, giao thức phát hành USDf — đồng đô la tổng hợp được đúc bằng tài sản thế chấp là crypto, stablecoin và tài sản thực đã token hóa. Người nắm giữ có thể staking FF để nhận quyền lợi trong giao thức và biểu quyết về các tham số. Token ra mắt năm 2025 và có trên Ethereum và BNB Smart Chain.","fetch-ai":"FET là token của Artificial Superintelligence Alliance, liên minh hình thành năm 2024 khi Fetch.ai hợp nhất token với AGIX của SingularityNET (và ban đầu cả OCEAN của Ocean Protocol). FET dùng để trả phí dịch vụ trong mạng tác tử AI tự động của Fetch.ai, staking để bảo mật mạng và tham gia quản trị. Token có mặt trên Ethereum, Cardano, BNB Smart Chain và các mạng thuộc hệ Cosmos.","filecoin":"Filecoin (FIL) là token gốc của một mạng lưu trữ phi tập trung do Protocol Labs xây dựng, mainnet ra mắt năm 2020. Người dùng trả FIL để lưu trữ và truy xuất dữ liệu, còn nhà cung cấp lưu trữ khóa FIL làm tài sản thế chấp và nhận FIL khi duy trì tệp luôn sẵn sàng. Mạng dùng các bằng chứng mật mã như bằng chứng sao chép (proof-of-replication) và bằng chứng không-thời gian (proof-of-spacetime) để kiểm tra dữ liệu có thực sự được lưu trữ.","first-digital-usd":"First Digital USD (FDUSD) là stablecoin đô la Mỹ do First Digital Labs phát hành, thuộc tập đoàn First Digital có trụ sở tại Hồng Kông, ra mắt năm 2023. Mỗi token được thiết kế để bảo chứng 1:1 bằng tiền mặt và các khoản tương đương tiền như tín phiếu Kho bạc Mỹ ngắn hạn được lưu ký. FDUSD được dùng làm cặp giao dịch, để thanh toán và chuyển đô la giữa các mạng như Ethereum, BNB Smart Chain, Solana, Sui và TON.","flare-networks":"FLR là token gốc của Flare, blockchain layer 1 tương thích EVM, token bắt đầu được phân phối từ tháng 1/2023, một phần qua airdrop cho người nắm giữ XRP. Flare tích hợp công cụ dữ liệu ngay trong giao thức, như Flare Time Series Oracle (FTSO) cung cấp giá và Flare Data Connector. FLR được dùng để trả phí, staking, ủy quyền cho nhà cung cấp dữ liệu và quản trị.","floki":"FLOKI là meme token do cộng đồng dẫn dắt, ra mắt năm 2021 và được đặt theo tên chú chó Shiba Inu của Elon Musk. Ngoài nguồn gốc meme, dự án đã xây dựng các sản phẩm như trò chơi blockchain Valhalla và bộ công cụ DeFi FlokiFi, người nắm giữ có thể tham gia bỏ phiếu quản trị. Token tồn tại trên cả Ethereum và BNB Smart Chain.","frax":"FRAX, nay được ghi là Legacy Frax Dollar, là stablecoin đầu tiên của Frax Finance, ra mắt tháng 12/2020 để bám theo đô la Mỹ. Ban đầu nó dùng mô hình một phần thế chấp, một phần thuật toán, sau đó chuyển sang thế chấp toàn phần. Về sau Frax giới thiệu frxUSD làm stablecoin đô la chính, nên token cũ này được đánh dấu là phiên bản cũ (legacy).","gatechain-token":"Gate (GT) là token của hệ sinh thái sàn Gate, được phát hành lần đầu năm 2019 với tên GateToken. Token dùng để giảm phí giao dịch, tham gia sự kiện trên nền tảng và làm token gas cho blockchain riêng của sàn. Gate định kỳ mua lại và đốt GT, giúp tổng cung giảm dần theo thời gian.","gho":"GHO là stablecoin phi tập trung do giao thức Aave phát hành năm 2023, được thiết kế để bám theo đô la Mỹ. Người dùng tạo GHO bằng cách vay nó dựa trên tài sản mã hóa đã gửi vào Aave, nên mỗi đơn vị GHO được đảm bảo bởi tài sản thế chấp có giá trị cao hơn. Lãi suất vay và các tham số khác do quản trị Aave quyết định, và GHO có mặt trên Ethereum cùng một số mạng khác.","global-dollar":"Global Dollar (USDG) là stablecoin đô la Mỹ do Paxos phát hành và được hỗ trợ bởi Global Dollar Network, một nhóm các công ty tiền mã hóa và fintech. Mỗi USDG được bảo chứng bằng dự trữ tiền mặt và tương đương tiền, được thiết kế để đổi 1:1 sang đô la. USDG được phát hành theo khung quản lý stablecoin của Singapore và có trên các mạng như Ethereum, Solana và Arbitrum.","gnosis":"GNO là token của Gnosis, dự án tập trung vào Ethereum thành lập năm 2015, nơi khai sinh các công cụ như ví đa chữ ký Safe và CoW Swap. Ngày nay GNO chủ yếu dùng để bảo vệ Gnosis Chain, mạng tương thích EVM đã hợp nhất với chuỗi xDai trước đây, nơi validator stake GNO để tạo khối. Người nắm giữ cũng dùng GNO để bỏ phiếu trong GnosisDAO, tổ chức quản lý ngân quỹ và định hướng dự án.","grass":"Grass là mạng lưới nơi người dùng chia sẻ băng thông internet chưa dùng đến qua tiện ích trình duyệt hoặc ứng dụng; băng thông này được dùng để thu thập dữ liệu web công khai phục vụ huấn luyện AI. GRASS là token của dự án trên Solana, dùng để thưởng cho người tham gia, staking vào các router của mạng và quản trị. Token được phân phối lần đầu qua đợt airdrop cộng đồng năm 2024.","grx-chain":"GRX là đồng coin gốc của GRX Chain, dự án chạy trên blockchain riêng và được xếp vào nhóm token liên quan đến sàn giao dịch. Các đồng coin gốc như vậy thường dùng để trả phí giao dịch trên mạng và cho các tiện ích trong hệ sinh thái của dự án.","hash-2":"HASH là token gốc của Provenance Blockchain, một mạng bằng chứng cổ phần xây dựng bằng Cosmos SDK và được thiết kế cho các dịch vụ tài chính như khoản vay, chứng khoán và hồ sơ quỹ. Công ty fintech Mỹ Figure Technologies giữ vai trò dẫn dắt việc tạo ra mạng này. HASH dùng để trả phí mạng, được validator và người ủy quyền stake để bảo vệ mạng và bỏ phiếu quản trị.","hedera-hashgraph":"HBAR là đồng coin gốc của Hedera, một mạng công khai đạt đồng thuận bằng công nghệ hashgraph thay vì blockchain truyền thống. HBAR dùng để trả phí giao dịch, hợp đồng thông minh và lưu trữ tệp, đồng thời có thể staking để góp phần bảo mật mạng. Hedera được giám sát bởi một hội đồng gồm các doanh nghiệp và tổ chức lớn, và nổi bật với mức phí thấp được định theo đô la Mỹ.","htx-dao":"HTX DAO (HTX) là token của hệ sinh thái sàn HTX, tiền thân là sàn Huobi. Ra mắt năm 2024, token dùng cho quản trị HTX DAO, nơi người nắm giữ bỏ phiếu cho các đề xuất, và cho các quyền lợi trên nền tảng. Người nắm giữ Huobi Token (HT) cũ có thể chuyển đổi sang HTX, hiện lưu hành trên TRON, Ethereum và BNB Smart Chain.","hyperliquid":"HYPE là token gốc của Hyperliquid, một blockchain lớp 1 được xây dựng quanh sổ lệnh trên chuỗi dành cho hợp đồng tương lai vĩnh cửu và giao dịch giao ngay. HYPE dùng để trả phí gas, được staking cho các validator vận hành cơ chế đồng thuận HyperBFT và có vai trò trong quản trị. Token ra mắt cuối năm 2024, với phần lớn được phân phối cho người dùng sớm qua airdrop.","injective-protocol":"INJ là token gốc của Injective, blockchain layer 1 xây dựng bằng Cosmos SDK cho các ứng dụng tài chính như giao dịch sổ lệnh, phái sinh và tài sản thực được token hóa. INJ được staking để bảo vệ mạng bằng chứng cổ phần, đồng thời dùng để trả phí và tham gia quản trị. Một phần phí giao thức được đưa vào các phiên đấu giá đốt định kỳ, loại bỏ vĩnh viễn INJ khỏi lưu thông.","instadapp":"FLUID là token quản trị của Fluid, giao thức DeFi trước đây có tên Instadapp; token INST cũ được đổi tên thành FLUID vào năm 2024. Fluid kết hợp cho vay và sàn giao dịch phi tập trung trên một lớp thanh khoản dùng chung, nên cùng một khoản tiền gửi có thể vừa làm tài sản thế chấp vừa làm thanh khoản giao dịch. Người nắm giữ bỏ phiếu về các tham số giao thức, vốn hoạt động trên Ethereum và nhiều mạng khác.","internet-computer":"ICP là token gốc của Internet Computer, blockchain do DFINITY Foundation phát triển, ra mắt năm 2021 và có thể chạy toàn bộ ứng dụng web cùng dữ liệu trực tiếp trên chuỗi. ICP được chuyển đổi thành cycles để trả chi phí tính toán và lưu trữ, và có thể khóa trong neuron để bỏ phiếu quản trị mạng. Ngoài ra còn có phiên bản cầu nối trên Ethereum và Base.","iota":"IOTA là đồng coin gốc của mạng IOTA, dự án khởi động năm 2016 và được IOTA Foundation có trụ sở tại Berlin hỗ trợ. Ban đầu mạng dùng cấu trúc không khối gọi là Tangle, hướng tới IoT và dữ liệu; năm 2025 chuyển sang kiến trúc mới IOTA Rebased với bằng chứng cổ phần ủy quyền và hợp đồng thông minh Move. IOTA được dùng để trả phí mạng và staking.","janus-henderson-anemoy-aaa-clo-fund":"JAAA là phiên bản token hóa của chứng chỉ quỹ đầu tư vào các nghĩa vụ cho vay có thế chấp (CLO) xếp hạng AAA, tức loại chứng khoán gom nhiều khoản vay doanh nghiệp. Quỹ do công ty quản lý tài sản Janus Henderson vận hành và được đưa lên chuỗi bởi Anemoy, đơn vị phát hành gắn với mạng lưới tài sản thực Centrifuge. Token có mặt trên Ethereum, Base, Solana và các mạng khác, thường chỉ dành cho nhà đầu tư đủ điều kiện.","jasmycoin":"JASMY là token của Jasmy, một công ty Nhật Bản do các cựu lãnh đạo Sony thành lập, tập trung vào thiết bị Internet vạn vật (IoT) và dữ liệu cá nhân. Mục tiêu là giúp mọi người tự kiểm soát dữ liệu do thiết bị của mình tạo ra và tự quyết định cách chia sẻ. JASMY là token ERC-20 trên Ethereum, được dùng trong nền tảng dữ liệu này.","jito-governance-token":"JTO là token quản trị của Jito, dự án trên Solana nổi tiếng với JitoSOL, một token staking thanh khoản, và client validator Jito xử lý MEV, tức giá trị phát sinh thêm từ việc sắp xếp thứ tự giao dịch. Người nắm giữ JTO bỏ phiếu trong Jito DAO về mức phí, sử dụng ngân quỹ và thay đổi giao thức. Token được phân phối qua airdrop vào tháng 12 năm 2023.","jupiter-exchange-solana":"Jupiter (JUP) là token của Jupiter, bộ tổng hợp sàn phi tập trung trên Solana, giúp chia mỗi lệnh hoán đổi qua nhiều nguồn thanh khoản để tìm đường giao dịch hiệu quả. JUP dùng cho quản trị qua Jupiter DAO, nơi người nắm giữ bỏ phiếu về đề xuất và các dự án ra mắt mới. Token được phân phối qua đợt airdrop cộng đồng lớn vào tháng 1 năm 2024.","just":"JUST (JST) là token quản trị của JUST, nền tảng tài chính phi tập trung xây dựng trên TRON và ra mắt năm 2020. Người nắm giữ bỏ phiếu cho các đề xuất về sản phẩm, như thị trường cho vay JustLend, và JST cũng được dùng để trả một số loại phí của giao thức. Một phần doanh thu của nền tảng được dùng để mua lại và đốt JST.","kaia":"Kaia (KAIA) là blockchain layer 1 hình thành năm 2024 từ việc sáp nhập Klaytn do Kakao khởi xướng và Finschia do LINE khởi xướng, hai mạng gắn với các ứng dụng nhắn tin lớn ở châu Á. KAIA thay thế các token cũ KLAY và FNSA, dùng để trả phí, stake và quản trị. Chuỗi tương thích EVM và nhắm đến ví cùng mini-app tiếp cận qua các ứng dụng nhắn tin như Kakao và LINE.","kamino":"KMNO là token quản trị của Kamino Finance, nền tảng DeFi trên Solana kết hợp cho vay và đi vay, các kho thanh khoản tự động và vị thế đòn bẩy trong cùng một giao diện. Người nắm giữ dùng KMNO để bỏ phiếu cho các quyết định của giao thức và có thể stake ngay trong Kamino. Token được phân phối cho người dùng sớm qua đợt airdrop năm 2024.","kaspa":"Kaspa (KAS) là tiền mã hóa dùng bằng chứng công việc, xây dựng trên cấu trúc blockDAG cho phép nhiều khối được tạo song song thay vì nối thành một chuỗi duy nhất. Thiết kế dựa trên giao thức GHOSTDAG này giúp thời gian tạo khối rất ngắn và xác nhận nhanh. KAS dùng cho thanh toán và phí giao dịch, và mạng ra mắt công bằng vào tháng 11 năm 2021, không đào trước.","kinesis-gold":"Kinesis Gold (KAU) là tiền kỹ thuật số được bảo chứng bằng vàng, mỗi token đại diện cho một gram vàng vật chất được phân bổ và lưu giữ trong kho. Token thuộc hệ thống tiền tệ Kinesis, nơi một phần phí giao dịch được chia lại cho người nắm giữ và người dùng như một khoản lợi suất. KAU có thể nắm giữ, chuyển hoặc chi tiêu, và vàng phía sau có thể được rút theo quy định của nền tảng.","kinesis-silver":"KAG là token do Kinesis phát hành, mỗi đơn vị đại diện cho một troy ounce bạc vật chất được lưu giữ theo hình thức phân bổ trong kho. Token cho phép nắm giữ, chuyển và chi tiêu bạc dưới dạng số, và kim loại có thể được quy đổi theo điều khoản của bên phát hành. Trong hệ thống Kinesis, KAG dùng để thanh toán và lưu giữ giá trị, và có phiên bản trên Ethereum.","kite-2":"KITE là token gốc của Kite, blockchain tập trung vào thanh toán và danh tính cho các tác nhân AI, để phần mềm tự động có danh tính kiểm chứng được và tự trả tiền dịch vụ. Kite là mạng tương thích EVM xây dựng bằng công nghệ Avalanche, và KITE được dùng để stake, bảo mật mạng, quản trị và khuyến khích hệ sinh thái. Token cũng có mặt trên Ethereum, BNB Smart Chain và Hyperliquid.","kucoin-shares":"KuCoin Token (KCS) là token gốc của sàn KuCoin, ra mắt năm 2017. Token dùng để giảm phí giao dịch và nhận các quyền lợi khác trên nền tảng, đồng thời là token gas của KCC (KuCoin Community Chain). KuCoin thường xuyên mua lại và đốt KCS, với kế hoạch dài hạn giảm nguồn cung xuống 100 triệu token.","layerzero":"ZRO là token của LayerZero, giao thức khả năng tương tác cho phép ứng dụng gửi thông điệp và token giữa các blockchain khác nhau. LayerZero không phải là một chuỗi riêng mà vận hành các hợp đồng điểm cuối trên nhiều mạng như Ethereum, Arbitrum, Base và BNB Smart Chain. ZRO ra mắt năm 2024 và được dùng cho quản trị giao thức.","leo-token":"LEO Token (LEO) là token tiện ích của iFinex – công ty đứng sau sàn Bitfinex – ra mắt năm 2019. Người nắm giữ có thể dùng LEO để giảm phí giao dịch và nhận các ưu đãi khác trên Bitfinex và các nền tảng liên quan. iFinex cam kết mua lại và đốt LEO theo thời gian, khiến nguồn cung lưu hành giảm dần. Token tồn tại trên Ethereum và các mạng khác.","lido-dao":"LDO là token quản trị của Lido, dịch vụ staking thanh khoản cho phép người dùng gửi ETH và nhận stETH, một token vẫn dùng được trong DeFi trong khi tích lũy phần thưởng staking. Người nắm giữ LDO bỏ phiếu trong Lido DAO về tham số giao thức, việc chọn nhà vận hành node và chi tiêu ngân quỹ. Token ra mắt trên Ethereum cuối năm 2020 và cũng có mặt trên nhiều mạng layer 2.","lighter":"LIT là token gốc của Lighter, sàn giao dịch phi tập trung chuyên về hợp đồng tương lai vĩnh cửu (perpetual futures). Lighter hoạt động như một zero-knowledge rollup trên Ethereum, dùng bằng chứng mật mã để chứng minh lệnh đã được khớp và thanh toán đúng. LIT được phát hành trên Ethereum và cũng có mặt trên Robinhood Chain.","litecoin":"Litecoin (LTC) là một trong những tiền mã hóa sớm nhất, được Charlie Lee ra mắt năm 2011 như một phiên bản nhẹ và nhanh hơn của Bitcoin. Litecoin chạy trên blockchain bằng chứng công việc riêng dùng thuật toán Scrypt, khoảng 2,5 phút tạo một khối mới. LTC chủ yếu được dùng để thanh toán và chuyển tiền, với tổng cung tối đa 84 triệu đồng, gấp bốn lần Bitcoin.","mantle":"Mantle (MNT) là token gốc của Mantle Network, một mạng lớp 2 của Ethereum gom các giao dịch lại và quyết toán trên Ethereum. MNT dùng để trả phí gas trên Mantle và bỏ phiếu quản trị. Dự án phát triển từ BitDAO, và token BIT đã được chuyển đổi thành MNT vào năm 2023.","memecore":"MemeCore (M) là dự án xây dựng quanh văn hóa meme, tự giới thiệu là một blockchain dành riêng cho memecoin và cộng đồng của chúng. Token M thuộc nhóm meme và hiện có dưới dạng token trên BNB Smart Chain.","meteora":"MET là token của Meteora, giao thức thanh khoản trên Solana có các pool được nhà giao dịch, các đợt ra mắt token mới và nhiều ứng dụng DeFi sử dụng. Meteora nổi tiếng với các pool động như mô hình DLMM, phân bổ thanh khoản theo từng khoảng giá và điều chỉnh phí theo biến động thị trường. MET ra mắt năm 2025 và được dùng cho quản trị giao thức.","midnight-3":"NIGHT là token gốc của Midnight, blockchain tập trung vào quyền riêng tư do đội ngũ đứng sau Cardano phát triển và vận hành như một chuỗi đối tác của Cardano. Midnight dùng bằng chứng không tiết lộ (zero-knowledge proof) để ứng dụng giữ kín dữ liệu nhạy cảm mà vẫn chứng minh được các quy tắc đã được tuân thủ. Nắm giữ NIGHT sẽ tạo ra DUST, một tài nguyên được che giấu dùng để trả phí giao dịch, còn NIGHT được dùng cho quản trị và sản xuất khối.","monad":"Monad (MON) là đồng coin gốc của Monad, blockchain layer 1 tương thích Ethereum ra mắt mainnet vào tháng 11 năm 2025. Mạng hướng đến thông lượng cao nhờ thực thi giao dịch song song và cơ chế đồng thuận riêng MonadBFT, trong khi vẫn chạy được hợp đồng thông minh Ethereum tiêu chuẩn. MON dùng để trả phí gas và được validator cùng người ủy quyền stake để bảo vệ mạng.","monero":"Monero (XMR) là tiền mã hóa tập trung vào quyền riêng tư, ra mắt năm 2014, mặc định giữ kín chi tiết giao dịch. Monero kết hợp chữ ký vòng, địa chỉ ẩn và giao dịch bảo mật để che giấu người gửi, người nhận và số tiền. Đồng này được đào bằng thuật toán bằng chứng công việc RandomX dành cho CPU phổ thông, và vẫn duy trì một phần thưởng khối nhỏ vĩnh viễn (tail emission) sau khi phần cung chính đã phát hành xong.","morpho":"MORPHO là token quản trị của Morpho, một giao thức cho vay phi tập trung trên Ethereum và các mạng EVM khác như Base. Morpho cho phép bất kỳ ai tạo thị trường cho vay tách biệt, còn các vault do bên quản lý độc lập điều hành sẽ phân bổ tiền gửi vào những thị trường đó. Người nắm giữ MORPHO bỏ phiếu trong Morpho DAO về nâng cấp và ngân quỹ của giao thức.","mx-token":"MX là token nền tảng của MEXC, sàn giao dịch tiền mã hóa tập trung thành lập năm 2018. Nắm giữ hoặc sử dụng MX có thể giúp người dùng được giảm phí giao dịch, tham gia sự kiện mở bán token mới và bỏ phiếu niêm yết trên MEXC. MX được phát hành dưới dạng token ERC-20 trên Ethereum và cũng có trên Morph L2.","near":"NEAR Protocol (NEAR) là blockchain lớp 1 dùng bằng chứng cổ phần, hoạt động từ năm 2020, với thiết kế phân mảnh (sharding) tên Nightshade giúp chia tải trên toàn mạng. NEAR dùng để trả phí giao dịch và lưu trữ, và được staking cho các validator. Dự án ngày càng tập trung vào AI và các tác tử do người dùng sở hữu; đồng sáng lập Illia Polosukhin là đồng tác giả bài báo nổi tiếng 'Attention Is All You Need'.","neo":"NEO là đồng coin gốc của Neo, blockchain hợp đồng thông minh thành lập tại Trung Quốc năm 2014 với tên Antshares và đổi tên năm 2017. Neo đạt đồng thuận bằng cơ chế chịu lỗi Byzantine ủy quyền (dBFT). NEO dùng cho quản trị, bao gồm bầu hội đồng vận hành đồng thuận, và việc nắm giữ NEO sẽ tạo ra GAS – token riêng dùng để trả phí mạng. Tổng cung NEO cố định ở 100 triệu và không thể chia nhỏ.","nexo":"NEXO là token của Nexo, nền tảng cho vay tiền mã hóa và tài sản số thành lập năm 2018. Số NEXO người dùng nắm giữ trên nền tảng quyết định hạng thành viên, từ đó ảnh hưởng đến lãi suất vay và các quyền lợi tài khoản khác. NEXO khởi đầu là token ERC-20 trên Ethereum và hiện cũng có trên một số mạng khác như Polygon.","non-playable-coin":"Non-Playable Coin (NPC) là meme token lấy tên từ trò đùa trên mạng về những người cư xử như nhân vật nền trong trò chơi điện tử. Token ra mắt trên Ethereum năm 2023 và được thiết kế để token và một bộ sưu tập NFT liên kết có thể chuyển đổi qua lại. Từ đó, NPC đã được bắc cầu sang Solana, BNB Smart Chain, Base và các mạng khác.","official-trump":"Official Trump (TRUMP) là meme token trên Solana gắn với Donald Trump, ra mắt vào tháng 1/2025 ngay trước lễ nhậm chức của ông. Token không có công dụng giao thức như trả phí hay staking mà chủ yếu là token sưu tầm và cộng đồng. Phần lớn nguồn cung được phân bổ cho các đơn vị liên quan và mở khóa dần theo lịch trình kéo dài nhiều năm.","okb":"OKB là token tiện ích của hệ sinh thái OKX. Token mang lại ưu đãi giảm phí giao dịch và quyền lợi trên nền tảng, đồng thời là token gas của X Layer, mạng lớp 2 riêng của OKX. Năm 2025, một đợt đốt token lớn đã cố định tổng cung OKB ở mức 21 triệu, nghĩa là không thể tạo thêm OKB mới.","olympus":"OHM là token của Olympus, giao thức DeFi ra mắt trên Ethereum năm 2021, duy trì một ngân quỹ tài sản dùng để hỗ trợ token. Olympus quản lý nguồn cung OHM bằng mua lại và cơ chế theo biên độ, và người nắm giữ có thể vay stablecoin bằng cách thế chấp OHM đã stake qua tính năng Cooler Loans. OHM cũng là token quản trị của OlympusDAO.","ondo-finance":"ONDO là token quản trị của Ondo Finance, dự án đưa các tài sản tài chính truyền thống như quỹ trái phiếu kho bạc Mỹ lên blockchain dưới dạng token. Người nắm giữ ONDO tham gia vào các quyết định về hệ sinh thái Ondo và sản phẩm của nó. Token chạy trên Ethereum, và các sản phẩm token hóa của Ondo hướng tới cả tổ chức lẫn người dùng on-chain.","open-usd":"Open USD (OUSD) là một stablecoin được thiết kế để giữ giá trị 1 đô la Mỹ. Đồng này được phát hành dưới dạng token trên nhiều mạng như Ethereum, Solana, Base và Tempo, có thể dùng để thanh toán, chuyển tiền và làm số dư đô la trong ứng dụng on-chain.","optimism":"OP là token quản trị của Optimism Collective, tổ chức giám sát OP Mainnet, một mạng layer 2 của Ethereum dùng optimistic rollup để gom giao dịch và quyết toán trên Ethereum. Người nắm giữ bỏ phiếu trong Token House về nâng cấp, chương trình khuyến khích và tài trợ, còn phí trên OP Mainnet được trả bằng ETH chứ không phải OP. Token ra mắt năm 2022, và bộ phần mềm OP Stack còn vận hành một nhóm chuỗi gọi là Superchain.","origintrail":"TRAC là token của OriginTrail, dự án vận hành Đồ thị Tri thức Phi tập trung (DKG) để công bố và liên kết dữ liệu có thể xác minh, ứng dụng trong chuỗi cung ứng và các ứng dụng AI. TRAC được dùng để công bố tài sản tri thức lên mạng và được các nhà vận hành node – những người lưu trữ và cung cấp dữ liệu – stake. Đây là token ERC-20 trên Ethereum, có phiên bản trên Base.","pancakeswap-token":"CAKE là token của PancakeSwap, sàn giao dịch phi tập trung ra mắt trên BNB Smart Chain năm 2020 và sau đó mở rộng sang Ethereum, Arbitrum, Base, Aptos cùng nhiều mạng khác. Người dùng hoán đổi token qua các pool thanh khoản tự động, và CAKE được dùng cho khuyến khích thanh khoản, staking và bỏ phiếu quản trị. Một phần phí của nền tảng được dùng để mua lại và đốt CAKE, giúp giảm nguồn cung.","pax-gold":"PAX Gold (PAXG) là token được bảo chứng bằng vàng do Paxos, một công ty ủy thác chịu quản lý tại Mỹ, phát hành từ năm 2019. Mỗi token đại diện cho quyền sở hữu một troy ounce vàng ròng dạng thỏi London Good Delivery được cất giữ trong kho chuyên nghiệp. Là token ERC-20 trên Ethereum, PAXG cho phép nắm giữ và chuyển vàng theo những phần rất nhỏ.","paypal-usd":"PayPal USD (PYUSD) là stablecoin đô la Mỹ do Paxos phát hành cho PayPal, ra mắt năm 2023. Mỗi token được bảo chứng bằng tiền gửi đô la, trái phiếu kho bạc Mỹ ngắn hạn và các khoản tương đương tiền, được thiết kế để đổi 1:1. PYUSD có thể gửi và chi tiêu trong PayPal và Venmo, đồng thời lưu hành trên các blockchain như Ethereum, Solana và Arbitrum.","pearl-2":"Pearl (PRL) là đồng coin gốc của blockchain riêng và được xếp vào nhóm AI. Giống phần lớn các coin lớp 1, PRL được dùng để trả phí mạng và hỗ trợ vận hành chuỗi.","pendle":"Pendle là giao thức DeFi ra mắt năm 2021, tách tài sản sinh lợi thành hai phần: token gốc (PT) và token lợi suất (YT), có thể giao dịch riêng. Nhờ vậy người dùng có thể chốt một mức lợi suất cố định hoặc đặt vị thế vào lợi suất tương lai. Token PENDLE dùng cho quản trị và có thể được khóa hoặc staking để nhận một phần doanh thu giao thức và định hướng phần thưởng.","pepe":"Pepe (PEPE) là một memecoin ra mắt trên Ethereum vào tháng 4 năm 2023, lấy tên từ meme Internet Pepe the Frog. Đồng này không có lộ trình chính thức hay công dụng tích hợp nào ngoài việc là token cộng đồng được giao dịch và chia sẻ. Tổng cung cố định khoảng 420,69 nghìn tỷ token đã được phát hành ngay khi ra mắt, và có các phiên bản bắc cầu trên những chuỗi khác.","pi-network":"Pi (PI) là đồng coin gốc của Pi Network, dự án khởi động năm 2019 cho phép người dùng tích lũy coin qua ứng dụng điện thoại thay vì đào tốn nhiều điện năng. Mainnet mở hoạt động từ tháng 2/2025, sau nhiều năm số dư chỉ dùng được trong hệ sinh thái của ứng dụng. Cơ chế đồng thuận dựa trên Stellar Consensus Protocol, và người dùng thường phải xác minh danh tính trước khi chuyển coin lên mainnet.","pieverse":"PIEVERSE là token của Pieverse, một dự án thuộc lĩnh vực AI đang xây dựng hạ tầng cho các tác nhân AI, bao gồm thanh toán on-chain. Token được phát hành trên BNB Smart Chain và Ethereum, dùng để tham gia vào hệ sinh thái Pieverse.","plasma":"Plasma là blockchain lớp 1 được thiết kế riêng cho thanh toán bằng stablecoin, đặc biệt là USDT, với các tính năng như chuyển USDT miễn phí. Mạng tương thích EVM và neo trạng thái vào Bitcoin để tăng bảo mật; bản beta mainnet ra mắt vào tháng 9/2025. XPL là token gốc, dùng để trả phí cho các thao tác khác và được validator staking để bảo vệ mạng.","polkadot":"DOT là đồng coin gốc của Polkadot, mạng lưới do đồng sáng lập Ethereum Gavin Wood khởi xướng, kết nối nhiều blockchain chuyên biệt vào một lớp bảo mật chung. DOT dùng cho quản trị on-chain, staking theo cơ chế bằng chứng cổ phần được đề cử (NPoS) và để có không gian khối cho các chuỗi kết nối. Mainnet Polkadot ra mắt năm 2020.","polygon-ecosystem-token":"POL là token gốc của mạng Polygon và là bản nâng cấp của MATIC, được người nắm giữ chuyển đổi theo tỷ lệ 1:1 từ tháng 9 năm 2024. POL dùng để trả phí gas trên Polygon PoS và được các validator stake để bảo mật mạng. Token cũng được thiết kế để phục vụ các chuỗi khác kết nối qua AggLayer của Polygon.","pudgy-penguins":"PENGU là token của Pudgy Penguins, thương hiệu chim cánh cụt hoạt hình khởi đầu là bộ sưu tập NFT trên Ethereum năm 2021, sau đó mở rộng sang đồ chơi và truyền thông. PENGU ra mắt trên Solana vào tháng 12/2024 và được airdrop rộng rãi cho người nắm giữ NFT cùng các cộng đồng crypto khác. Token chủ yếu đóng vai trò token cộng đồng và meme, hiện có mặt trên nhiều mạng.","pump-fun":"PUMP là token của Pump.fun, nền tảng trên Solana cho phép bất kỳ ai tạo và phát hành memecoin chỉ trong vài bước, với giai đoạn giao dịch đầu tiên chạy trên đường cong liên kết (bonding curve). Token PUMP ra mắt năm 2025 và gắn với hệ sinh thái cũng như cộng đồng của nền tảng. Đây là token Solana nên được lưu trong các ví hỗ trợ Solana.","pyth-network":"PYTH là token của Pyth Network, một oracle cung cấp giá thị trường cho các ứng dụng blockchain. Dữ liệu đến trực tiếp từ các nguồn phát hành gốc như sàn giao dịch và công ty giao dịch; mạng bắt đầu trên Solana rồi mở rộng sang nhiều chuỗi khác. PYTH được dùng cho quản trị và cơ chế staking buộc các nhà cung cấp dữ liệu chịu trách nhiệm về chất lượng giá.","quant-network":"QNT là token của Quant, công ty có công nghệ Overledger nhằm kết nối các blockchain khác nhau với nhau và với hệ thống doanh nghiệp hiện có. Doanh nghiệp và nhà phát triển dùng QNT để trả phí giấy phép và quyền truy cập mạng Quant. Token chạy trên Ethereum và có nguồn cung giới hạn khoảng 14,6 triệu QNT.","railgun":"RAIL là token quản trị của Railgun, giao thức quyền riêng tư cho Ethereum và các mạng EVM khác. Railgun dùng bằng chứng không tiết lộ (zero-knowledge) để người dùng có thể giữ, gửi và hoán đổi token trong số dư được che chắn mà không công khai lịch sử địa chỉ. Người stake RAIL được bỏ phiếu thay đổi giao thức và nhận một phần phí thu khi tài sản ra vào hệ thống riêng tư.","rain":"Rain (RAIN) là token thuộc lĩnh vực tài chính phi tập trung (DeFi), được phát hành trên Arbitrum One – một mạng lớp 2 của Ethereum. Là token trên Arbitrum, RAIN được chuyển và sử dụng trong các ví và ứng dụng tương thích Ethereum, còn phí mạng được trả bằng ETH chứ không phải RAIN.","raydium":"RAY là token của Raydium, nhà tạo lập thị trường tự động (AMM) và nền tảng thanh khoản trên Solana ra mắt năm 2021. Người dùng hoán đổi token và cung cấp thanh khoản cho các pool, và nhiều token mới trên Solana mở pool giao dịch đầu tiên tại Raydium. RAY được dùng cho staking và khuyến khích thanh khoản, đồng thời một phần phí giao dịch được dùng để mua lại RAY.","re-protocol-reusd":"reUSD là token tính theo đô la của Re Protocol, dự án kết nối vốn on-chain với thị trường tái bảo hiểm, nơi các công ty bảo hiểm chuyển một phần rủi ro sang doanh nghiệp khác. Token được thiết kế để giữ giá trị ổn định theo đô la và được hỗ trợ bởi các tài sản liên quan đến tái bảo hiểm. reUSD có mặt trên nhiều mạng, gồm Ethereum, Solana, Arbitrum, Base và Avalanche.","render-token":"Render (RENDER) là token của Render Network, mạng kết nối những người cần sức mạnh GPU cho kết xuất 3D và tác vụ AI với các nhà vận hành node có GPU nhàn rỗi. Người đặt việc trả phí bằng RENDER, còn nhà vận hành nhận RENDER cho công việc đã hoàn thành. Dự án do Jules Urbach, nhà sáng lập OTOY, khởi xướng và đã chuyển từ Ethereum sang Solana năm 2023, thay thế token RNDR cũ.","ripple":"XRP là tài sản gốc của XRP Ledger, một blockchain công khai ra mắt năm 2012 và gắn liền với công ty Ripple. Mạng lưới được thiết kế cho thanh toán nhanh, chi phí thấp và quyết toán xuyên biên giới; giao dịch được xác nhận trong vài giây bằng cơ chế đồng thuận thay vì đào coin. Toàn bộ 100 tỷ XRP được tạo ra ngay từ đầu, và mỗi giao dịch tiêu hủy một khoản phí rất nhỏ.","ripple-usd":"Ripple USD (RLUSD) là stablecoin đô la Mỹ do Ripple phát hành, ra mắt vào tháng 12 năm 2024. RLUSD được bảo chứng bằng tiền gửi đô la, trái phiếu kho bạc Mỹ ngắn hạn và các khoản tương đương tiền, được thiết kế để đổi 1:1. Đồng này được phát hành gốc trên cả XRP Ledger và Ethereum, chủ yếu hướng tới thanh toán và nhu cầu của tổ chức.","safo":"SAFO là phần sở hữu được token hóa của một quỹ kiểu thị trường tiền tệ do Spiko, công ty fintech tại Paris, cung cấp; quỹ cơ sở do công ty quản lý tài sản Amundi quản lý. Quỹ theo dõi lãi suất qua đêm thông qua hợp đồng hoán đổi, và token cho phép nhà đầu tư đủ điều kiện nắm giữ, chuyển nhượng chứng chỉ quỹ trên blockchain công khai. SAFO được phát hành trên nhiều mạng như Ethereum, Arbitrum, Base, Polygon, Starknet và Stellar.","sei-network":"Sei là blockchain lớp 1 thiết kế cho các ứng dụng giao dịch tốc độ cao, với độ hoàn tất dưới một giây và xử lý giao dịch song song. Từ bản nâng cấp v2, Sei chạy EVM song song nên có thể triển khai hợp đồng thông minh kiểu Ethereum. SEI dùng để trả phí gas, staking bảo mật mạng bằng chứng cổ phần và tham gia quản trị; mainnet ra mắt tháng 8/2023.","shiba-inu":"Shiba Inu (SHIB) là token meme ra mắt năm 2020 bởi một nhà sáng lập ẩn danh có tên Ryoshi, được đặt theo giống chó nổi tiếng nhờ Dogecoin. SHIB khởi đầu là token ERC-20 trên Ethereum và phát triển thành hệ sinh thái cộng đồng gồm sàn phi tập trung ShibaSwap và mạng lớp 2 Shibarium. Nguồn cung của SHIB lên tới hàng trăm nghìn tỷ token, và một phần đã bị đốt.","shuffle-2":"SHFL là token của Shuffle, một nền tảng trò chơi trực tuyến chấp nhận tiền mã hóa. Đây là token ERC-20 trên Ethereum, được dùng trong nền tảng cho các tính năng như chương trình phần thưởng và rút thăm dành cho người nắm giữ. Vai trò của nó gắn chặt với chính nền tảng Shuffle chứ không phải một blockchain hay giao thức độc lập.","sky":"Sky (SKY) là token quản trị của giao thức Sky, tên mới của MakerDAO từ năm 2024. Người nắm giữ bỏ phiếu về tham số rủi ro và tài sản thế chấp của giao thức, nơi phát hành stablecoin USDS bên cạnh DAI cũ. SKY là phiên bản nâng cấp của MKR, mỗi MKR có thể đổi thành 24.000 SKY.","societe-generale-forge-eurcv":"EUR CoinVertible (EURCV) là stablecoin đồng euro do Societe Generale-FORGE, công ty con chuyên về tài sản số của ngân hàng Pháp Société Générale, phát hành. Mỗi token được thiết kế có giá trị một euro và được bảo chứng bằng dự trữ euro do bên phát hành nắm giữ. Ra mắt lần đầu trên Ethereum năm 2023, hiện EURCV cũng có trên Solana, Stellar và XRP Ledger, dùng cho thanh toán và quyết toán.","sofiusd":"SoFiUSD là stablecoin đô la Mỹ do SoFi phát hành, một công ty tài chính tiêu dùng của Mỹ có giấy phép ngân hàng quốc gia. Đồng này được thiết kế để có thể đổi 1:1 sang đô la, dựa trên dự trữ do bên phát hành nắm giữ, và là một trong số ít stablecoin do một ngân hàng Mỹ chịu quản lý phát hành trực tiếp. SoFiUSD chạy trên Ethereum và Solana, hướng đến thanh toán và quyết toán.","solana":"Solana (SOL) là đồng coin gốc của blockchain Solana, hoạt động từ năm 2020 với mục tiêu thông lượng cao và phí thấp. SOL dùng để trả phí giao dịch và được ủy thác staking cho các validator bảo vệ mạng lưới theo cơ chế bằng chứng cổ phần. Một kỹ thuật đánh dấu thời gian gọi là Proof of History giúp sắp xếp thứ tự giao dịch, và Solana có nhiều ứng dụng DeFi, NFT và thanh toán.","sonic-3":"S là đồng coin gốc của Sonic, mạng trước đây mang tên Fantom, được khởi chạy lại với tên mới và chuỗi nâng cấp vào cuối năm 2024. Người nắm giữ FTM có thể chuyển sang S theo tỷ lệ 1:1. S dùng để trả phí giao dịch, stake để bảo vệ mạng và tham gia quản trị; Sonic tương thích EVM và chia lại cho nhà phát triển một phần phí mà ứng dụng của họ tạo ra.","spiko-amundi-overnight-swap-fund-eur":"EURSAFO là chứng chỉ quỹ được token hóa của một quỹ bằng euro do Spiko, công ty fintech tại Paris, ra mắt cùng công ty quản lý tài sản Amundi. Mỗi token đại diện cho một chứng chỉ quỹ có giá trị hướng theo lãi suất qua đêm của đồng euro, và được ghi nhận trực tiếp trên các blockchain công khai. Token được phát hành trên nhiều mạng như Ethereum, Arbitrum, Base, Polygon, Starknet và Stellar.","stable-2":"STABLE là token gốc của Stable, blockchain layer 1 được xây dựng riêng cho thanh toán bằng stablecoin, lấy USDT làm trọng tâm. Trên Stable, phí giao dịch được trả bằng USDT thay vì một đồng gas riêng, nên người dùng có thể gửi đô la mà không cần nắm giữ token khác. STABLE đảm nhận vai trò khác: hỗ trợ bảo mật mạng và quản trị.","starknet":"STRK là token gốc của Starknet, mạng layer 2 của Ethereum do StarkWare phát triển. Starknet là một validity rollup: gom nhiều giao dịch và chứng minh tính đúng đắn với Ethereum bằng bằng chứng mật mã STARK, còn hợp đồng thông minh được viết bằng ngôn ngữ Cairo. STRK ra mắt năm 2024, dùng để trả phí giao dịch, staking và quản trị.","stellar":"Stellar (XLM), còn gọi là lumen, là tài sản gốc của mạng Stellar, được Jed McCaleb và tổ chức phi lợi nhuận Stellar Development Foundation ra mắt năm 2014. Mạng lưới tập trung vào thanh toán và phát hành tài sản token hóa như stablecoin, sử dụng Stellar Consensus Protocol thay vì đào coin. XLM dùng để trả phí giao dịch nhỏ và mỗi tài khoản cần giữ một số dư tối thiểu.","sui":"SUI là đồng coin gốc của Sui, một blockchain lớp 1 do Mysten Labs phát triển, công ty được thành lập bởi các cựu kỹ sư dự án Diem của Meta. SUI dùng để trả phí giao dịch, staking cho các validator để bảo mật mạng và tham gia quản trị. Mainnet ra mắt năm 2023, sử dụng ngôn ngữ lập trình Move, và tổng cung tối đa là 10 tỷ SUI.","sun-token":"SUN là token quản trị của SUN.io, nền tảng DeFi trên blockchain TRON cung cấp hoán đổi stablecoin, pool thanh khoản và sàn phi tập trung SunSwap. Người nắm giữ có thể khóa SUN để bỏ phiếu cho các đề xuất và tăng phần tham gia của mình trong các chương trình khai thác thanh khoản. Dự án ra đời năm 2020 trong hệ sinh thái của Justin Sun, nhà sáng lập TRON.","swissborg":"BORG là token của SwissBorg, ứng dụng đầu tư tiền mã hóa có trụ sở tại Thụy Sĩ, thành lập năm 2017. BORG thay thế token CHSB trước đây trong đợt chuyển đổi năm 2024 và được dùng trong ứng dụng để mở các hạng thành viên cao hơn cùng những quyền lợi khác. Token được phát hành trên Ethereum và Solana.","syrup":"SYRUP là token của Maple Finance, nền tảng cho vay on-chain cấp tín dụng cho các tổ chức và cung cấp sản phẩm như syrupUSDC. Năm 2024, SYRUP thay thế token MPL trước đây của Maple, với tỷ lệ 1 MPL đổi lấy 100 SYRUP. Người nắm giữ có thể stake SYRUP và tham gia quản trị giao thức.","terra-luna":"Terra Luna Classic (LUNC) là đồng coin gốc của blockchain Terra ban đầu, vốn sụp đổ vào tháng 5 năm 2022 khi stablecoin thuật toán UST mất neo với đô la. Sau sự cố, một chuỗi mới nhận tên LUNA, còn chuỗi cũ và đồng coin của nó được đổi tên thành Terra Classic và LUNC. Mạng dựa trên Cosmos SDK này hiện do cộng đồng vận hành, và LUNC dùng để trả phí, stake và quản trị, kể cả bỏ phiếu về việc đốt token.","tether":"Tether (USDT) là stablecoin do công ty Tether phát hành từ năm 2014, được thiết kế để giữ giá trị bằng một đô la Mỹ. Công ty cho biết mỗi token được bảo chứng bằng dự trữ, chủ yếu là tín phiếu Kho bạc Mỹ ngắn hạn và các khoản tương đương tiền mặt. USDT được dùng rộng rãi để giao dịch, thanh toán và chuyển đô la giữa các nền tảng, và có mặt trên nhiều mạng như Ethereum, TRON và Solana.","tether-gold":"Tether Gold (XAUT) là token do Tether phát hành, trong đó mỗi đơn vị đại diện cho quyền sở hữu một troy ounce vàng vật chất được cất giữ trong kho ở Thụy Sĩ. Token cho phép nắm giữ và chuyển vàng trên blockchain, kể cả với phần nhỏ của một ounce. XAUT hoạt động dưới dạng token trên Ethereum, và người nắm giữ có thể tra cứu các thỏi vàng cụ thể được phân bổ cho địa chỉ của mình.","tezos":"Tezos (XTZ) là blockchain layer 1 có mainnet ra mắt năm 2018. Mạng dùng cơ chế bằng chứng cổ phần thanh khoản: người nắm giữ có thể tự tạo khối (gọi là baking) hoặc ủy quyền cho một baker, và các bản nâng cấp giao thức được đề xuất, bỏ phiếu ngay trên chuỗi nên không cần hard fork. XTZ dùng để trả phí giao dịch và phí hợp đồng thông minh.","the-graph":"The Graph (GRT) là token của một giao thức lập chỉ mục phi tập trung, sắp xếp dữ liệu blockchain thành các API mở gọi là subgraph để ứng dụng truy vấn thay vì tự vận hành máy chủ dữ liệu. Indexer stake GRT để cung cấp dịch vụ, người ủy quyền giao GRT cho indexer và curator dùng GRT để đánh dấu subgraph hữu ích. Phí truy vấn được trả bằng GRT; mainnet ra mắt tháng 12 năm 2020.","the-open-network":"Gram (GRAM), trước đây gọi là Toncoin, là đồng coin gốc của The Open Network (TON), một blockchain bằng chứng cổ phần (proof-of-stake) có thiết kế khởi nguồn từ Telegram và hiện do một cộng đồng độc lập phát triển. Đồng coin dùng để trả phí mạng, để validator staking, và cho thanh toán cũng như mini app trong hệ sinh thái Telegram. Ngoài ra còn có phiên bản wrapped trên Ethereum và BNB Smart Chain.","the-sandbox":"SAND là token của The Sandbox, thế giới ảo và nền tảng tạo game thuộc sở hữu của Animoca Brands, nơi người chơi xây dựng, sở hữu và vận hành trải nghiệm trên đất số. SAND dùng để mua mảnh đất LAND và tài sản trong game, trả phí nền tảng, cũng như để stake và bỏ phiếu quản trị. Đây là token ERC-20 trên Ethereum, có phiên bản trên Polygon và Base.","theta-token":"THETA là token quản trị và staking của Theta Network, blockchain ra mắt năm 2019 cho việc phân phối video phi tập trung và gần đây mở rộng sang điện toán AI, GPU qua dịch vụ EdgeCloud. Theta dùng hai token: THETA được các node xác thực và node bảo vệ stake để giữ an toàn cho chuỗi, còn TFUEL dùng để trả phí giao dịch và dịch vụ. Tổng cung THETA cố định ở mức 1 tỷ.","thorchain":"RUNE là tài sản gốc của THORChain, mạng cho phép hoán đổi coin gốc giữa các blockchain, ví dụ BTC lấy ETH, mà không cần token bọc. Mỗi pool thanh khoản đều ghép một tài sản với RUNE, và các nhà vận hành node phải ký quỹ RUNE để bảo vệ các kho chứa tiền của người dùng. THORChain được xây dựng bằng Cosmos SDK và bắt đầu giao dịch xuyên chuỗi từ năm 2021.","tradable-na-rent-financing-platform-sstn":"Token này đại diện cho một vị thế tín dụng tư nhân được token hóa: khoản tiếp xúc với một hạn mức tài trợ ở Bắc Mỹ dùng để tài trợ các khoản thanh toán tiền thuê nhà, phát hành qua nền tảng Tradable. Token chạy trên zkSync, một mạng lớp 2 của Ethereum, và thường dành cho nhà đầu tư tổ chức và nhà đầu tư đủ điều kiện hơn là giao dịch hằng ngày. Mã PC0000031 là mã sản phẩm, và việc nắm giữ thường giới hạn cho người tham gia hợp lệ.","tron":"TRON (TRX) là đồng coin gốc của blockchain TRON do Justin Sun sáng lập năm 2017. TRX dùng để nhận tài nguyên mạng gọi là băng thông và năng lượng, và có thể staking để bỏ phiếu cho 27 Siêu đại diện (Super Representative) tạo khối theo cơ chế bằng chứng cổ phần ủy quyền. TRON là một trong những mạng được dùng nhiều nhất để chuyển stablecoin USDT.","true-usd":"TrueUSD (TUSD) là stablecoin đô la Mỹ ra mắt năm 2018, được thiết kế để có thể quy đổi 1:1 sang đô la nằm trong dự trữ. Ban đầu do đội ngũ TrustToken tạo ra, hiện TUSD do Techteryx phát hành, với báo cáo dự trữ được công bố qua xác nhận của bên thứ ba. TUSD được dùng cho thanh toán, cặp giao dịch và DeFi trên Ethereum, TRON, BNB Smart Chain và các mạng khác.","trust-wallet-token":"TWT là token của Trust Wallet, ứng dụng ví tiền mã hóa tự lưu ký được Binance mua lại năm 2018. Ra mắt năm 2020, TWT được dùng cho các ưu đãi trong ứng dụng như giảm phí và để tham gia các tính năng cộng đồng. Token ban đầu phát hành trên BNB Beacon Chain cũ, hiện chủ yếu lưu hành trên BNB Smart Chain.","unibase":"UB là token của Unibase, một dự án AI tự giới thiệu là lớp bộ nhớ phi tập trung cho các tác nhân AI, giúp chúng lưu trữ và chia sẻ dữ liệu dài hạn giữa các ứng dụng. Token được phát hành trên BNB Smart Chain và Ethereum, dùng cho quyền truy cập, ưu đãi và tham gia hệ sinh thái. Vì là dự án mới, chi tiết mô hình token có thể còn thay đổi.","uniswap":"UNI là token quản trị của Uniswap, một sàn giao dịch phi tập trung cho phép hoán đổi token trực tiếp từ ví thông qua các pool thanh khoản tự động thay vì sổ lệnh. Người nắm giữ UNI bỏ phiếu về các thay đổi của giao thức và cách sử dụng quỹ cộng đồng. Token ra mắt năm 2020 bằng đợt airdrop cho người dùng trước đó, và Uniswap sau này còn ra mắt mạng lớp 2 riêng trên Ethereum là Unichain.","united-stables":"United Stables (U) là stablecoin được thiết kế để giữ giá trị một đô la Mỹ. Giống các stablecoin đô la khác, U được dùng để chuyển giá trị giữa ví và nền tảng, giao dịch và làm đơn vị ổn định trong DeFi. Đồng này được phát hành trên nhiều mạng, gồm BNB Smart Chain, Ethereum và TRON.","usa":"USAT là stablecoin đô la Mỹ được thiết kế để giữ giá trị một-một với đô la, có trên Ethereum và Celo. Các stablecoin như USAT dùng để chuyển giá trị đô la trên chuỗi, thanh toán và quyết toán, cũng như làm tài sản ổn định trong giao dịch và DeFi. Việc bảo chứng dự trữ và điều kiện quy đổi do bên phát hành quy định, vì vậy bạn nên đọc các công bố của chính họ.","usd-coin":"USDC là stablecoin gắn với đô la Mỹ do Circle phát hành, ra mắt năm 2018. Mỗi token được thiết kế để đổi lấy một đô la theo tỷ lệ 1:1 và được bảo chứng bằng tiền mặt cùng trái phiếu Kho bạc Mỹ ngắn hạn, với báo cáo dự trữ định kỳ. USDC được dùng trong giao dịch, thanh toán và DeFi, và được phát hành gốc trên nhiều blockchain như Ethereum, Sui, Hedera và XRP Ledger.","usd1-wlfi":"USD1 là stablecoin neo theo đô la Mỹ do World Liberty Financial ra mắt năm 2025. Mỗi token được thiết kế để đổi 1:1 sang đô la và được bảo chứng bằng dự trữ gồm tiền mặt, trái phiếu kho bạc Mỹ ngắn hạn và các khoản tương đương tiền, do BitGo lưu ký. USD1 được phát hành trên nhiều mạng, gồm Ethereum, BNB Smart Chain, Solana và TRON.","usdai":"USDai là token neo theo đô la Mỹ do giao thức USD.AI phát hành; giao thức này đưa vốn on-chain vào các khoản vay được thế chấp bằng phần cứng tính toán AI như GPU. Người dùng có thể giữ USDai như một đơn vị giá trị ổn định hoặc stake trong giao thức để nhận phiên bản đã stake gắn với hoạt động cho vay đó. Token lưu hành trên Arbitrum, Ethereum, Base và Plasma.","usdd":"USDD là stablecoin neo theo đô la Mỹ, ra đời trên mạng TRON năm 2022. Đồng này nhắm giữ giá trị một đô la và được bảo chứng bằng quỹ dự trữ tài sản tiền mã hóa có giá trị cao hơn lượng USDD đang lưu hành. USDD chủ yếu được dùng cho thanh toán, cặp giao dịch và cho vay trong hệ sinh thái DeFi của TRON, và cũng được phát hành trên Ethereum và BNB Smart Chain.","usdgo":"USDGO là stablecoin được thiết kế để bám theo đô la Mỹ theo tỷ lệ một đổi một. Đồng này được dùng như các stablecoin đô la khác: giữ số dư ổn định, chuyển giá trị giữa các ví và làm đơn vị tính trong giao dịch và DeFi. USDGO được phát hành trên Solana, Ethereum và Morph L2.","usds":"USDS là stablecoin gắn với đô la Mỹ do Sky phát hành – giao thức trước đây có tên MakerDAO – ra mắt năm 2024 như phiên bản nâng cấp của DAI; DAI và USDS có thể chuyển đổi theo tỷ lệ 1:1. USDS được tạo ra dựa trên tài sản thế chấp gửi vào giao thức, gồm tài sản mã hóa và tài sản thực (RWA), và lưu hành trên Ethereum, Base, Arbitrum và Solana.","usdtb":"USDtb là stablecoin đô la do Ethena, đội ngũ đứng sau USDe, phát hành vào cuối năm 2024. Khác với USDe, USDtb chủ yếu được bảo chứng bằng chứng chỉ của BUIDL, quỹ trái phiếu Kho bạc Mỹ token hóa của BlackRock, cùng dự trữ tương đương tiền mặt, thay vì các vị thế crypto phòng hộ. Token được dùng làm tài sản thanh toán ổn định và là một phần dự trữ cho các sản phẩm khác của Ethena.","useless-3":"Useless Coin (USELESS) là meme token ra mắt trên Solana năm 2025 và công khai tự nhận là “vô dụng”. Sức hút của nó đến từ chính trò đùa và cộng đồng trực tuyến xung quanh, chứ không phải từ sản phẩm hay giao thức nào. Token này cũng có phiên bản trên BNB Smart Chain.","usual-usd":"USD0 là stablecoin đô la do giao thức Usual phát hành, được thiết kế để bảo chứng 1:1 bằng tài sản thực ngắn hạn như tín phiếu Kho bạc Mỹ đã token hóa. Người dùng có thể gửi USD0 vào các sản phẩm staking của Usual để nhận token giao thức USUAL, và USD0 còn là tài sản nền cho cho vay và pool thanh khoản DeFi. Token hoạt động trên Ethereum và nhiều chuỗi EVM khác.","usx":"USX là stablecoin phát hành trên Solana, hướng tới duy trì giá trị một đô la Mỹ cho mỗi token. Giống các token neo theo đô la khác, USX chủ yếu dùng để thanh toán, chuyển giá trị giữa các ứng dụng và làm đơn vị ổn định trong các giao thức DeFi. Cơ chế giữ neo và tài sản bảo chứng do bên phát hành quy định, nên bạn nên xem thông tin dự trữ hoặc tài sản thế chấp mà họ công bố.","vaulta":"Vaulta (A) là coin gốc của mạng Vaulta, blockchain trước đây mang tên EOS, đổi thương hiệu vào năm 2025 và hoán đổi EOS sang A theo tỷ lệ 1:1. Chuỗi dùng cơ chế bằng chứng cổ phần ủy quyền (DPoS) và định hướng vào dịch vụ ngân hàng, thanh toán Web3. A dùng để trả tài nguyên mạng và có thể stake để góp phần bảo mật chuỗi.","vechain":"VET là token gốc của VeChainThor, blockchain công khai ra mắt năm 2018, tập trung vào truy xuất chuỗi cung ứng và ứng dụng doanh nghiệp. VeChain dùng mô hình hai token: nắm giữ VET sẽ tạo ra VTHO, và VTHO mới là token thực sự được dùng để trả phí giao dịch. Mạng vận hành theo cơ chế đồng thuận kiểu bằng chứng thẩm quyền với các trình xác thực đã được công khai danh tính và kiểm duyệt.","venice-token":"Venice Token (VVV) là token của Venice.ai, nền tảng AI chú trọng quyền riêng tư do Erik Voorhees sáng lập, chạy các mô hình mã nguồn mở mà không lưu cuộc trò chuyện của người dùng. Stake VVV cho phép người nắm giữ dùng một phần dung lượng API AI của Venice mà không phải trả phí cho từng yêu cầu. Token ra mắt vào tháng 1 năm 2025 trên Base, một mạng lớp 2 của Ethereum.","virtual-protocol":"Virtuals Protocol là nền tảng tạo và đồng sở hữu các tác tử AI, chủ yếu trên Base, nơi mỗi tác tử có thể có token riêng. VIRTUAL là tài sản nền của hệ sinh thái: token của tác tử mới được ghép cặp với VIRTUAL trong pool thanh khoản, và VIRTUAL cũng dùng để trả phí dịch vụ cũng như ra mắt tác tử. Dự án trước đây là PathDAO, một guild game, và đổi tên thành Virtuals năm 2024.","whitebit":"WhiteBIT Coin (WBT) là token tiện ích của sàn giao dịch tiền mã hóa WhiteBIT, một nền tảng được thành lập tại Ukraina. Người nắm giữ có thể dùng WBT để nhận ưu đãi trong hệ sinh thái WhiteBIT, như giảm phí giao dịch và truy cập các tính năng của nền tảng. Token ban đầu được phát hành trên Ethereum và TRON, và cũng được dùng trên Whitechain, blockchain do đội ngũ WhiteBIT phát triển.","world-liberty-financial":"WLFI là token quản trị của World Liberty Financial, một dự án tài chính phi tập trung ra mắt năm 2024 và có liên hệ với gia đình Tổng thống Mỹ Donald Trump. Người nắm giữ có thể bỏ phiếu cho các đề xuất về nền tảng và sản phẩm, trong đó có stablecoin USD1. Ban đầu token không thể chuyển nhượng và bắt đầu được giao dịch từ năm 2025.","worldcoin-wld":"WLD là token của World (trước đây là Worldcoin), dự án do Sam Altman đồng sáng lập và Tools for Humanity phát triển. Dự án hướng tới cung cấp cho mỗi người một bằng chứng số bảo vệ quyền riêng tư rằng họ là con người duy nhất, gọi là World ID, được xác minh bằng thiết bị quét mống mắt có tên Orb. WLD dùng cho quản trị và khuyến khích hệ sinh thái, chạy trên Ethereum, Optimism và World Chain.","wormhole":"W là token quản trị của Wormhole, giao thức nhắn tin cho phép các blockchain như Solana, Ethereum và nhiều mạng khác trao đổi dữ liệu và token với nhau. Các thông điệp xuyên chuỗi được xác minh bởi mạng lưới 19 validator độc lập gọi là Guardian. W ra mắt năm 2024 cùng đợt airdrop lớn cho cộng đồng và được thiết kế là token đa chuỗi gốc, di chuyển giữa các mạng mà không cần đóng gói (wrap).","xdce-crowd-sale":"XDC là coin gốc của XDC Network, blockchain tương thích EVM do XinFin khởi xướng, hướng tới tài trợ thương mại và token hóa tài sản thực. Mạng dùng cơ chế bằng chứng cổ phần ủy quyền có tên XDPoS, trong đó các masternode tạo khối nhanh với chi phí thấp. XDC dùng để trả phí giao dịch và được các nhà vận hành masternode staking; mã định danh của trang này nhắc tới XDCE, token từ đợt bán cộng đồng ban đầu của dự án.","ylds":"YLDS là token đô la có trả lãi do Figure phát hành trên blockchain Provenance. Khác với phần lớn stablecoin, YLDS được đăng ký với SEC Mỹ như một chứng khoán và trả lãi cho người nắm giữ, với dự trữ đặt trong các tài sản ngắn hạn chất lượng cao. Token hướng tới thanh toán và quyết toán khi người dùng muốn một token tính bằng đô la đồng thời nhận lãi.","zama":"ZAMA là token của Zama Protocol, do Zama phát triển – một công ty mật mã học nổi tiếng với nghiên cứu về mã hóa đồng cấu hoàn toàn (FHE). FHE cho phép xử lý dữ liệu mà không cần giải mã, và Zama dùng công nghệ này để bổ sung số dư bảo mật và hợp đồng thông minh riêng tư cho các blockchain hiện có. Token dùng để trả phí dịch vụ của giao thức và được các nhà vận hành mạng stake.","zcash":"Zcash (ZEC) là tiền mã hóa tập trung vào quyền riêng tư, ra mắt năm 2016 và chạy trên blockchain bằng chứng công việc riêng. Zcash dùng bằng chứng không tiết lộ (zk-SNARKs) để người dùng gửi giao dịch được che chắn, ẩn người gửi, người nhận và số tiền; còn giao dịch minh bạch hoạt động gần giống Bitcoin. ZEC được dùng để thanh toán và có tổng cung tối đa 21 triệu.","zebec-network":"ZBCN là token của Zebec Network, một dự án thanh toán khởi đầu trên Solana, nổi tiếng với thanh toán dạng dòng chảy, trong đó tiền đến tay người nhận theo từng giây, chẳng hạn khi trả lương. Dự án còn phát triển thẻ crypto và các sản phẩm kết nối tài sản số với thanh toán hằng ngày. ZBCN dùng cho quản trị và staking, đồng thời đã thay thế token ZBC trước đây."});
